#define main preserved_native_main
#include "../overlay-cuda/main.cu"
#undef main
#include <vector>
#include <cstring>
std::vector<unsigned char> readbytes(const char*name){FILE*f=fopen(name,"rb");if(!f)exit(3);fseek(f,0,SEEK_END);size_t bytes=ftell(f);rewind(f);std::vector<unsigned char>v(bytes);if(fread(v.data(),1,bytes,f)!=bytes)exit(4);fclose(f);return v;}
int main(){auto raw=readbytes("study_input_f32.bin"),br=readbytes("study_boxes_i32.bin"),er=readbytes("study_expected_f64.bin");std::vector<Box>boxes(br.size()/sizeof(Box));memcpy(boxes.data(),br.data(),br.size());float3*input,*output;cudaMalloc(&input,raw.size());cudaMalloc(&output,raw.size());cudaMemcpy(input,raw.data(),raw.size(),cudaMemcpyHostToDevice);cudaMemcpy(output,input,raw.size(),cudaMemcpyDeviceToDevice);float4 color=make_float4(255,204,203,1);
auto launch=[&](){for(const auto&box:boxes){dim3 threads(8,8),grid((box.width+7)/8,(box.height+7)/8);DetectionOverlayBox<float3><<<grid,threads>>>(input,output,640,480,box.left,box.top,box.width,box.height,color);}};cudaDeviceSynchronize();launch();if(cudaDeviceSynchronize()!=cudaSuccess)return 4;std::vector<double>prefix;for(size_t i=0;i<raw.size()/4;i++){float x;memcpy(&x,raw.data()+4*i,4);prefix.push_back(x);}for(size_t i=0;i<br.size()/4;i++){int32_t x;memcpy(&x,br.data()+4*i,4);prefix.push_back(x);}for(double x:{255.,204.,203.,1.,640.,480.,double(boxes.size())})prefix.push_back(x);bool allok=true;
for(int trial=1;trial<=5;trial++){cudaMemcpy(output,input,raw.size(),cudaMemcpyDeviceToDevice);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();launch();auto status=cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::vector<float>out(raw.size()/4);cudaMemcpy(out.data(),output,raw.size(),cudaMemcpyDeviceToHost);double error=0,relative=0;bool finite=true;std::vector<double>got=prefix;for(size_t i=0;i<out.size();i++){double expected;memcpy(&expected,er.data()+8*i,8);double d=fabs(double(out[i])-expected);error=std::max(error,d);relative=std::max(relative,d/std::max(fabs(expected),1e-3));finite&=std::isfinite(out[i]);got.push_back(out[i]);}bool ok=status==cudaSuccess&&finite&&error<=1e-3;allok&=ok;char name[80];snprintf(name,80,"output_trial%d.bin",trial);FILE*f=fopen(name,"wb");fwrite(got.data(),8,got.size(),f);fclose(f);
printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",got.size(),error,relative,name,got.size());}return allok?0:1;}
